package net.wchbdotnet.seedpriority;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.ObjectComposition;
import net.runelite.api.events.PostMenuSort;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@PluginDescriptor(
	name = "Seed Priority",
	description = "Prioritises farming destinations when using farming items",
	tags = {"farming", "seed", "sapling", "birdhouse", "patch", "leprechaun"}
)
public class SeedPriorityPlugin extends Plugin
{
	@Inject
	private Client client;

	@Subscribe(priority = -1)
	public void onPostMenuSort(PostMenuSort event)
	{
		if (client.isMenuOpen())
		{
			return;
		}

		Widget selectedWidget = client.getSelectedWidget();
		if (selectedWidget == null || selectedWidget.getItemId() < 0)
		{
			return;
		}

		ItemComposition selectedItem = client.getItemDefinition(selectedWidget.getItemId());
		if (selectedItem == null)
		{
			return;
		}

		Menu menu = client.getMenu();
		MenuEntry[] entries = menu.getMenuEntries();
		int bestIndex = SeedPriorityRules.bestDestinationIndex(entries, selectedItem.getName(), this::hasFarmingPatchActions);
		int currentTopIndex = entries.length - 1;
		if (bestIndex < 0 || bestIndex == currentTopIndex)
		{
			return;
		}

		MenuEntry currentTop = entries[currentTopIndex];
		entries[currentTopIndex] = entries[bestIndex];
		entries[bestIndex] = currentTop;
		menu.setMenuEntries(entries);
	}

	private boolean hasFarmingPatchActions(MenuEntry entry)
	{
		if (entry.getType() != MenuAction.WIDGET_TARGET_ON_GAME_OBJECT)
		{
			return false;
		}

		ObjectComposition object = client.getObjectDefinition(entry.getIdentifier());
		if (object == null)
		{
			return false;
		}

		if (object.getImpostorIds() != null)
		{
			ObjectComposition impostor = object.getImpostor();
			if (impostor != null)
			{
				object = impostor;
			}
		}

		return SeedPriorityRules.hasFarmingPatchActions(object.getActions());
	}
}

package net.wchbdotnet.seedpriority;

import java.util.Locale;
import java.util.function.Predicate;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.client.util.Text;

final class SeedPriorityRules
{
	private static final int TOOL_LEPRECHAUN_PRIORITY = 100;
	private static final int PATCH_PRIORITY = 200;
	private static final int COMPOST_BIN_PRIORITY = 300;
	private static final int BIRD_HOUSE_PRIORITY = 400;

	private SeedPriorityRules()
	{
	}

	static int bestDestinationIndex(
		MenuEntry[] entries,
		String selectedItemName,
		Predicate<MenuEntry> hasFarmingPatchActions)
	{
		int bestIndex = -1;
		int bestPriority = 0;
		for (int index = 0; index < entries.length; index++)
		{
			MenuEntry entry = entries[index];
			int priority = destinationPriority(
				entry.getType(),
				entry.getTarget(),
				selectedItemName,
				hasFarmingPatchActions.test(entry));
			if (priority >= bestPriority && priority > 0)
			{
				bestIndex = index;
				bestPriority = priority;
			}
		}
		return bestIndex;
	}

	static int destinationPriority(MenuAction action, String target, String selectedItemName)
	{
		return destinationPriority(action, target, selectedItemName, false);
	}

	static int destinationPriority(
		MenuAction action,
		String target,
		String selectedItemName,
		boolean hasFarmingPatchActions)
	{
		String destination = destinationName(target);
		String itemName = normalize(selectedItemName);

		if (action == MenuAction.WIDGET_TARGET_ON_GAME_OBJECT)
		{
			if (isBirdHouse(destination) && isSeed(itemName))
			{
				return BIRD_HOUSE_PRIORITY;
			}
			if (isCompostBin(destination))
			{
				return COMPOST_BIN_PRIORITY;
			}
			if ((isPatch(destination) || hasFarmingPatchActions) && isFarmingItem(itemName))
			{
				return PATCH_PRIORITY;
			}
		}
		else if (action == MenuAction.WIDGET_TARGET_ON_NPC && isToolLeprechaun(destination))
		{
			return TOOL_LEPRECHAUN_PRIORITY;
		}

		return 0;
	}

	static String destinationName(String target)
	{
		String plainTarget = normalize(target == null ? "" : Text.removeTags(target));
		int separator = plainTarget.lastIndexOf("->");
		return separator >= 0 ? plainTarget.substring(separator + 2).trim() : plainTarget;
	}

	static boolean isFarmingItem(String itemName)
	{
		String name = normalize(itemName);
		return isSeed(name)
			|| name.endsWith(" sapling")
			|| name.endsWith(" seedling")
			|| name.endsWith(" seedling (w)")
			|| name.contains("compost")
			|| name.equals("weeds")
			|| name.equals("rake")
			|| name.equals("spade")
			|| name.equals("seed dibber")
			|| name.equals("gardening trowel")
			|| name.equals("secateurs")
			|| name.equals("magic secateurs")
			|| name.startsWith("watering can")
			|| name.endsWith("plant pot")
			|| name.equals("plant cure")
			|| name.equals("scarecrow")
			|| name.equals("volcanic ash")
			|| name.equals("sulphurous fertiliser")
			|| name.equals("gricoller's fertiliser");
	}

	static boolean hasFarmingPatchActions(String[] actions)
	{
		if (actions == null)
		{
			return false;
		}

		boolean inspect = false;
		boolean guide = false;
		for (String action : actions)
		{
			if ("Inspect".equalsIgnoreCase(action))
			{
				inspect = true;
			}
			else if ("Guide".equalsIgnoreCase(action))
			{
				guide = true;
			}
		}
		return inspect && guide;
	}

	private static boolean isSeed(String itemName)
	{
		return normalize(itemName).endsWith(" seed") || normalize(itemName).endsWith(" seeds");
	}

	private static boolean isBirdHouse(String destination)
	{
		return destination.contains("bird house") || destination.contains("birdhouse");
	}

	private static boolean isCompostBin(String destination)
	{
		return destination.contains("compost bin");
	}

	private static boolean isPatch(String destination)
	{
		return destination.contains("patch") || destination.equals("allotment");
	}

	private static boolean isToolLeprechaun(String destination)
	{
		return destination.equals("tool leprechaun");
	}

	private static String normalize(String value)
	{
		return value == null ? "" : value.trim().toLowerCase(Locale.ENGLISH);
	}
}

package net.wchbdotnet.seedpriority;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class SeedPriorityPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(SeedPriorityPlugin.class);
		RuneLite.main(args);
	}
}

package net.wchbdotnet.seedpriority;

import java.lang.reflect.Proxy;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SeedPriorityRulesTest
{
	@Test
	public void extractsDestinationFromColouredUseTarget()
	{
		assertEquals(
			"teak bird house",
			SeedPriorityRules.destinationName("<col=ff9040>Barley seed<col=ffffff> -> <col=ffff>Teak bird house"));
	}

	@Test
	public void recognisesCoreFarmingItems()
	{
		assertTrue(SeedPriorityRules.isFarmingItem("Ranarr seed"));
		assertTrue(SeedPriorityRules.isFarmingItem("Oak sapling"));
		assertTrue(SeedPriorityRules.isFarmingItem("Oak seedling (w)"));
		assertTrue(SeedPriorityRules.isFarmingItem("Ultracompost"));
		assertTrue(SeedPriorityRules.isFarmingItem("Bottomless compost bucket"));
		assertTrue(SeedPriorityRules.isFarmingItem("Bucket of supercompost"));
		assertTrue(SeedPriorityRules.isFarmingItem("Watering can(8)"));
		assertFalse(SeedPriorityRules.isFarmingItem("Rune scimitar"));
	}

	@Test
	public void prioritisesSeedOnBirdHouseOverPlayer()
	{
		assertEquals(400, SeedPriorityRules.destinationPriority(
			MenuAction.WIDGET_TARGET_ON_GAME_OBJECT,
			"Barley seed -> Teak bird house",
			"Barley seed"));
		assertEquals(0, SeedPriorityRules.destinationPriority(
			MenuAction.WIDGET_TARGET_ON_PLAYER,
			"Barley seed -> Other player",
			"Barley seed"));
	}

	@Test
	public void doesNotTreatUnrelatedItemAsPatchIntent()
	{
		assertEquals(0, SeedPriorityRules.destinationPriority(
			MenuAction.WIDGET_TARGET_ON_GAME_OBJECT,
			"Rune scimitar -> Herb patch",
			"Rune scimitar"));
	}

	@Test
	public void prioritisesCompostBinsAndToolLeprechauns()
	{
		assertEquals(300, SeedPriorityRules.destinationPriority(
			MenuAction.WIDGET_TARGET_ON_GAME_OBJECT,
			"Watermelon -> Compost Bin",
			"Watermelon"));
		assertEquals(100, SeedPriorityRules.destinationPriority(
			MenuAction.WIDGET_TARGET_ON_NPC,
			"Cabbage -> Tool Leprechaun",
			"Cabbage"));
	}

	@Test
	public void prioritisesBottomlessBucketOnNamedHerbsOverPlayer()
	{
		MenuEntry herbs = menuEntry(
			MenuAction.WIDGET_TARGET_ON_GAME_OBJECT,
			"Bottomless compost bucket -> Ranarr");
		MenuEntry player = menuEntry(
			MenuAction.WIDGET_TARGET_ON_PLAYER,
			"Bottomless compost bucket -> jobergs (level-90)");

		assertEquals(0, SeedPriorityRules.bestDestinationIndex(
			new MenuEntry[]{herbs, player},
			"Bottomless compost bucket",
			entry -> entry == herbs));
	}

	@Test
	public void doesNotTreatUnrelatedInspectObjectAsPatch()
	{
		assertEquals(0, SeedPriorityRules.destinationPriority(
			MenuAction.WIDGET_TARGET_ON_GAME_OBJECT,
			"Bottomless compost bucket -> Display case",
			"Bottomless compost bucket",
			false));
	}

	@Test
	public void recognisesFarmingPatchActionSignature()
	{
		assertTrue(SeedPriorityRules.hasFarmingPatchActions(
			new String[]{"Pick", "Inspect", null, "Guide", null}));
		assertFalse(SeedPriorityRules.hasFarmingPatchActions(
			new String[]{"Inspect", null, null, null, null}));
		assertFalse(SeedPriorityRules.hasFarmingPatchActions(null));
	}

	private static MenuEntry menuEntry(MenuAction action, String target)
	{
		return (MenuEntry) Proxy.newProxyInstance(
			MenuEntry.class.getClassLoader(),
			new Class<?>[]{MenuEntry.class},
			(proxy, method, args) ->
			{
				if ("getType".equals(method.getName()))
				{
					return action;
				}
				if ("getTarget".equals(method.getName()))
				{
					return target;
				}
				throw new UnsupportedOperationException(method.getName());
			});
	}
}
